"use client";
import Link from "next/link";
import Image from "next/image";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { Badge, Button, EmptyState, TextInput } from "./ui";
import type { ProfileDTO } from "@/domain/types";
import { ProfilesPreview } from "./profiles";
export function LivePortrait({ profile }: { profile: Pick<ProfileDTO,"kind"|"demoKey"> }) {
  const [failed, setFailed] = useState(false);
  const key = profile.demoKey?.replace("stage4-", "");
  const source = !failed && profile.kind === "DEMO" && key && ["aanya", "ishaan", "lina", "omar"].includes(key) ? "/demo/portraits/" + key + ".webp" : "/demo/portraits/fallback.svg";
  return <Image className="portrait live-portrait" src={source} width={560} height={700} unoptimized alt={source.endsWith(".webp") ? "Generated portrait of a fictional adult" : "Neutral portrait placeholder"} onError={() => setFailed(true)} />;
}
export function ProfilesLive({ data, query }: { data: { profiles: ProfileDTO[]; total: number; page: number; pageSize: number }; query: { q?: string; city?: string; status?: string; kind?: string } }) {
  const router = useRouter();
  function changePage(page: number) { const params = new URLSearchParams({ ...query, page: String(page) }); router.push("/profiles?" + params); }
  return <><form className="filter-toolbar" action="/profiles"><div className="search-field"><label className="sr-only" htmlFor="live-search">Search profiles</label><TextInput id="live-search" type="search" name="q" defaultValue={query.q} maxLength={100} placeholder="Search name, city, occupation, or about…" /></div><label className="filter-field">City<TextInput name="city" defaultValue={query.city} maxLength={80} /></label><label className="filter-field">Status<select className="control" name="status" defaultValue={query.status ?? "ACTIVE"}><option value="ACTIVE">Active</option><option value="ARCHIVED">Archived</option><option value="ALL">All</option></select></label><label className="filter-field">Classification<select className="control" name="kind" defaultValue={query.kind ?? "ALL"}><option value="ALL">All profiles</option><option value="REAL">Real</option><option value="DEMO">Demo</option></select></label><Button type="submit">Filter</Button></form><div className="results-heading"><p role="status"><strong>{data.total}</strong> matching profiles</p><span className="muted small">Contacts stay private</span></div>{data.profiles.length ? <div className="profile-grid">{data.profiles.map(profile => <article className="profile-card panel" key={profile.id}><LivePortrait profile={profile} /><div className="profile-card-copy"><div className="profile-name-row"><h2>{profile.displayName}{profile.reportedAge !== null && ", " + profile.reportedAge}</h2><Badge tone={profile.kind === "DEMO" ? "warning" : "neutral"}>{profile.kind}</Badge></div><p className="muted small">{profile.city ?? "City unknown"} · {profile.status.toLowerCase()}</p><p className="profile-detail">{profile.occupation ?? "Occupation unknown"}</p><div className="tag-list">{profile.interests.slice(0,3).map(interest => <span className="tag" key={interest}>{interest}</span>)}</div><Link className="text-link" href={"/profiles/" + profile.id}>View profile →</Link></div></article>)}</div> : <div className="panel"><EmptyState title="A fresh space for profiles" description="Create a profile or clear your filters. Demo seeding is optional in Settings." action={<div className="button-row"><Link href="/profiles/new" className="button button-primary">Create a profile</Link><Link href="/profiles" className="button button-secondary">Clear filters</Link></div>} /></div>}<div className="workflow-navigation"><Button variant="secondary" disabled={data.page <= 1} onClick={() => changePage(data.page - 1)}>Previous page</Button><span className="muted small">Page {data.page} · 20 profiles per page</span><Button variant="secondary" disabled={data.page * data.pageSize >= data.total} onClick={() => changePage(data.page + 1)}>Next page</Button></div><details className="preview-states"><summary>Design state examples</summary><p className="muted">These four synthetic cards are separate visual demonstrations; they are not database records.</p><ProfilesPreview /></details></>;
}
